<script setup>
import { Link, useForm } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ user: Object, availableRoles: Array, jobRoles: Array });
const detail = props.user.detail_user || {};
const form = useForm({ name: props.user.name || '', username: props.user.username || '', email: props.user.email || '', role: props.user.role || 'student', job_id: props.user.job_id || '', exp: props.user.exp || 0, bio: detail.bio || '', experience: detail.experience || '', location: detail.location || '', skills_text: Array.isArray(detail.skills) ? detail.skills.join(', ') : '', password: '', password_confirmation: '', profile_photo: null, remove_avatar: false });
const save = () => form.transform(data => ({ ...data, _method: 'patch' })).post(route('admin.users.update',props.user.id), { forceFormData: true, onSuccess: () => form.reset('password','password_confirmation','profile_photo') });
</script>
<template><AssessmentLayout title="Edit pengguna" subtitle="Perbarui identitas, peran, dan profil pengguna." breadcrumb="Komunitas & pengguna"><div class="layout"><form class="panel" @submit.prevent="save"><div class="fields"><label>Nama<input v-model="form.name" required /><span class="error">{{ form.errors.name }}</span></label><label>Username<input v-model="form.username" /><span class="error">{{ form.errors.username }}</span></label><label>Email<input v-model="form.email" type="email" required /><span class="error">{{ form.errors.email }}</span></label><label>Peran<select v-model="form.role"><option v-for="role in availableRoles" :key="role" :value="role">{{ role }}</option></select><span class="error">{{ form.errors.role }}</span></label><label>Job / program<select v-model="form.job_id"><option value="">Tidak ada</option><option v-for="job in jobRoles" :key="job.id" :value="job.id">{{ job.name }}</option></select></label><label>EXP<input v-model.number="form.exp" type="number" min="0" /></label><label class="wide">Foto profil<input type="file" accept="image/png,image/jpeg" @change="form.profile_photo=$event.target.files[0]" /><span class="error">{{ form.errors.profile_photo }}</span></label><label class="wide"><span><input v-model="form.remove_avatar" type="checkbox" style="width:auto" /> Hapus foto saat ini</span></label><label class="wide">Bio<textarea v-model="form.bio" rows="4" /></label><label>Pengalaman<input v-model="form.experience" /></label><label>Lokasi<input v-model="form.location" /></label><label class="wide">Keahlian (pisahkan dengan koma)<input v-model="form.skills_text" /></label><label>Password baru<input v-model="form.password" type="password" autocomplete="new-password" /><span class="error">{{ form.errors.password }}</span></label><label>Konfirmasi password<input v-model="form.password_confirmation" type="password" autocomplete="new-password" /></label></div><div class="actions"><button class="primary" :disabled="form.processing">Simpan perubahan</button><Link class="secondary" :href="route('redesign.users')">Kembali</Link></div></form><aside><div class="panel"><h2>Pratinjau profil</h2><img v-if="user.profile_photo" :src="'/storage/'+user.profile_photo" alt="Foto profil saat ini" style="width:88px;height:88px;object-fit:cover;border-radius:50%" /><p><strong>{{ form.name }}</strong><br><span class="muted">@{{ form.username || '—' }}</span></p></div><div class="panel"><h2>Transaksi pengguna</h2><Link :href="route('redesign.users.ledger',user.id)">Lihat ledger →</Link></div></aside></div></AssessmentLayout></template>
